package com.samhanair.logis.partnerauth.config;
import com.samhanair.logis.common.http.HttpHeaderConstants; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException; import java.util.*; import java.util.Locale; import org.springframework.web.filter.OncePerRequestFilter;
public class PublicIdentityHeaderSanitizingFilter extends OncePerRequestFilter { private static final Set<String> H=HttpHeaderConstants.INBOUND_IDENTITY_HEADERS.stream().map(x->x.toLowerCase(Locale.ROOT)).collect(java.util.stream.Collectors.toUnmodifiableSet()); @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String p=r.getRequestURI();if(p.startsWith("/actuator/")||p.startsWith("/v3/api-docs/")||p.startsWith("/swagger-ui/")||"/swagger-ui.html".equals(p)||p.startsWith("/api/v1/auth/partner-"))c.doFilter(new W(r),s);else c.doFilter(r,s);} private static final class W extends HttpServletRequestWrapper{W(HttpServletRequest r){super(r);}static boolean clean(String n){return n!=null&&H.contains(n.toLowerCase(Locale.ROOT));}@Override public String getHeader(String n){return clean(n)?null:super.getHeader(n);}@Override public Enumeration<String> getHeaders(String n){return clean(n)?Collections.emptyEnumeration():super.getHeaders(n);}@Override public Enumeration<String> getHeaderNames(){Set<String>s=new HashSet<>(Collections.list(super.getHeaderNames()));s.removeIf(W::clean);return Collections.enumeration(s);}@Override public int getIntHeader(String n){return clean(n)?-1:super.getIntHeader(n);}@Override public long getDateHeader(String n){return clean(n)?-1:super.getDateHeader(n);}}}
